def reserve(stock: int, requested: int) -> int:
    if stock < 0:
        raise ValueError("stock must be non-negative")
    if requested < 0:
        raise ValueError("requested must be non-negative")
    if requested >= stock:
        raise ValueError("not enough stock")
    return stock - requested

